export type WordType = 'noun' | 'verb' | 'adjective' | 'adverb' | 'conjunction' | 'preposition' | 'phrase' | 'other';

// CEFR level a word is drawn from. Each level's study pool is exclusive —
// wordsForLevel(level) returns only words tagged exactly that level, not
// lower ones too. LEVEL_ORDER is still the canonical list/ordering of every
// known level, used for iteration (migration, sync) and the Settings
// dropdown, not for cumulative filtering.
// 'B2_old' was the original B2 import — its source PDF turned out to be the
// wrong wordlist, so it was set aside under this name (existing users' real
// progress on it is preserved, just no longer offered as a fresh choice) once
// 'B2' was repopulated from a correct source (dtz_wortliste_B2_new.pdf).
export type Level = 'A1' | 'A2' | 'B1' | 'B2' | 'B2_old' | 'C1' | 'C2';
export const LEVEL_ORDER: Level[] = ['A1', 'A2', 'B1', 'B2', 'B2_old', 'C1', 'C2'];

export interface Word {
  id: string;
  de: string;
  article?: 'der' | 'die' | 'das';
  plural?: string;
  en: string;
  type: WordType;
  category?: string;
  level: Level;
}

